-- public.companion_swap(p_world uuid, p_uid uuid, p_taking creature, OUT v_current integer, OUT v_to text, OUT v_why text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.companion_swap(p_world uuid, p_uid uuid, p_taking creature, OUT v_current integer, OUT v_to text, OUT v_why text)
 RETURNS record
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_cur creature; v_dd deed; v_freed int; v_adds int;
begin
  select * into v_cur from creature
   where world_id = p_world and keeper = p_uid and mode = 'active' and hitched_to is null and id <> p_taking.id limit 1;
  if v_cur.id is null then return; end if;
  v_current := v_cur.id;
  if v_cur.hitched_to is not null then v_why := v_cur.name || ' is in the traces: unhitch it first.'; return; end if;
  if v_cur.rider is not null then v_why := 'Get down off ' || v_cur.name || ' first.'; return; end if;
  v_dd := my_deed(p_world, p_uid);
  -- What the deed counts once the one being taken is off it and this one is on it.
  v_freed := case when p_taking.mode = 'deed' and p_taking.post is null then 1 else 0 end;
  v_adds := 1;
  if v_dd.world_id is not null
     and workers_on_deed(p_world, p_uid) - v_freed + v_adds <= worker_cap(p_world, p_uid) then
    v_to := 'deed';
    return;
  end if;
  if empty_crate(p_world, p_uid) is not null then
    v_why := pannier_exit_refusal(p_world, v_cur);
    if v_why is null then v_to := 'crate'; end if;
    return;
  end if;
  v_why := case when v_dd.world_id is not null
    then v_cur.name || ' has nowhere to go: ' || v_dd.name || ' full (' || worker_cap(p_world, p_uid)
         || ' workers at level ' || v_dd.level || '), no empty wildermon crate.'
    else v_cur.name || ' has nowhere to go: no settlement, no empty wildermon crate.' end;
end $function$
